INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bahasa Khmer Terasa Sangat Asing$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang Indonesia yang bepergian ke Kamboja merasa bahasa Khmer terdengar sangat asing: tulisannya memakai aksara sendiri, bunyinya tidak mirip bahasa Indonesia atau Inggris, dan kamus frasa kadang membingungkan. Akibatnya banyak wisatawan hanya mengandalkan bahasa Inggris atau bahasa isyarat. Padahal, orang Kamboja sangat menghargai tamu yang berusaha menyapa dalam bahasa mereka — satu sapaan yang benar bisa mencairkan suasana dan membuka percakapan yang ramah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Khmer Itu Bahasa Austroasia, Bukan Rumpun Sino-Tibet$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Khmer adalah bahasa resmi Kamboja dan dituturkan oleh sekitar 16 juta orang. Ia termasuk rumpun Austroasia — sama seperti bahasa Vietnam — bukan rumpun Sino-Tibet seperti Thai atau Mandarin. Kabar baiknya: bahasa Khmer tidak mengenal nada kata seperti Thai atau Vietnam, jadi pengucapannya relatif lebih mudah ditebak dari tulisannya dalam romanisasi. Aksara Khmer memang rumit, tetapi untuk percakapan sehari-hari Anda cukup menghafal frasa lisan tanpa harus bisa membaca aksaranya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Aplikasi kamus Khmer-Inggris/Indonesia di HP (bisa dipakai offline)$$, $$Catatan kecil berisi daftar sapaan (atau screenshot di galeri HP)$$, $$Aplikasi penerjemah suara untuk latihan pengucapan$$, $$Rasa percaya diri untuk mencoba — orang Kamboja umumnya sabar dan senang membantu$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: 10 Sapaan Dasar yang Paling Sering Dipakai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Halo (umum): Suostei — sapaan paling aman untuk siapa pun$$, $$Selamat pagi/siang/sore: Suostei — dipakai untuk semua waktu$$, $$Apa kabar?: Sok sabay te? — jawaban umum: Sok sabay (baik-baik saja)$$, $$Terima kasih: Awkun (dibaca aw-koon) — ucapkan dengan senyum$$, $$Sama-sama: Awkun dae — balasan yang sopan$$, $$Maaf/permisi: Som toh — untuk minta maaf atau lewat$$, $$Ya: Baat (laki-laki) / Cha (perempuan) — penutur menyesuaikan gender sendiri$$, $$Tidak: Ot te — penolakan yang sopan$$, $$Berapa harganya?: Tlay ponman? — wajib saat belanja di pasar$$, $$Sampai jumpa: Liah heuy — perpisahan yang hangat$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum Pemula$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kesalahan paling umum adalah memakai 'baat' atau 'cha' terbalik — ingat, ini mengikuti gender penutur, bukan lawan bicara. Kesalahan kedua: mengucapkan 'awkun' terlalu cepat sehingga terdengar seperti 'kun' saja; ucapkan perlahan aw-koon. Ketiga: jangan berasumsi semua orang Kamboja fasih bahasa Inggris di luar kota besar — di pasar tradisional dan desa, sapaan Khmer jauh lebih membantu. Terakhir, hindari menyentuh kepala orang (dianggap tidak sopan) saat menyapa; cukup membungkuk ringan dengan kedua tangan merapat (sampeas).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil: Sudah Bisa Berkomunikasi Dasar?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Bisa menyapa 'suostei' dan menjawab 'sok sabay' tanpa melihat catatan$$, $$Bisa mengucapkan terima kasih 'awkun' dan permisi 'som toh' dengan lancar$$, $$Bisa menawar harga dengan 'tlay ponman?' di pasar$$, $$Tahu perbedaan 'baat' dan 'cha' sesuai gender sendiri$$, $$Berani mencoba satu percakapan penuh 1 menit dengan penjual atau sopir tuk-tuk$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Lutut Sakit Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Lutut adalah sendi terbesar tubuh dan menanggung beban berat setiap hari: berjalan, naik tangga, jongkok, hingga berolahraga. Tidak heran nyeri lutut menjadi keluhan yang sangat umum, dari anak muda yang aktif berolahraga sampai lansia. Rasa sakitnya bisa berupa nyeri tumpul, kaku saat bangun pagi, bunyi 'krek' saat ditekuk, hingga bengkak yang membuat sulit berjalan. Kabar baiknya: sebagian besar nyeri lutut ringan bisa ditangani di rumah — asalkan Anda tahu penyebabnya dan kapan harus waspada.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: 5 Penyebab Umum Nyeri Lutut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Penyebab pertama adalah cedera ringan: terkilir, memar, atau otot tertarik akibat olahraga atau terpeleset. Kedua, penggunaan berlebihan (overuse): naik-turun tangga berlebihan, lari jarak jauh tanpa pemanasan, atau jongkok terlalu lama. Ketiga, radang sendi (osteoarthritis) yang umum pada usia di atas 50 tahun — tulang rawan menipis sehingga tulang bergesekan. Keempat, radang tendon (tendinitis) di sekitar tempurung lutut, sering dialami pelari dan pesepeda. Kelima, asam urat atau infeksi sendi yang biasanya disertai bengkak, kemerahan, dan demam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan: Yang Perlu Disiapkan di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Kompres dingin (es dibungkus handuk) untuk 48 jam pertama$$, $$Kompres hangat untuk nyeri kaku yang sudah lewat 2 hari$$, $$Perban elastis untuk menopang lutut yang bengkak ringan$$, $$Bantal untuk mengganjal kaki saat berbaring$$, $$Obat pereda nyeri yang dijual bebas (sesuai dosis kemasan)$$, $$Sepatu yang nyaman dan tidak aus solnya$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Metode RICE untuk Nyeri Lutut Ringan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Rest (istirahat): hentikan aktivitas yang memicu nyeri selama 1-2 hari, hindari jongkok dan naik tangga$$, $$Ice (es): kompres dingin 15-20 menit, 3-4 kali sehari pada 48 jam pertama untuk mengurangi bengkak$$, $$Compression (kompresi): balut dengan perban elastis secukupnya — jangan terlalu kencang sampai kesemutan$$, $$Elevation (tinggikan): ganjal kaki dengan bantal agar lutut lebih tinggi dari jantung saat berbaring$$, $$Setelah 2 hari: ganti ke kompres hangat dan lakukan peregangan ringan (tekuk-lurus perlahan)$$, $$Kembali beraktivitas bertahap: mulai jalan datar pendek sebelum kembali berolahraga$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tanda Bahaya: Segera ke Dokter Bila Ini Terjadi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Segera periksakan ke dokter atau IGD bila: lutut tidak bisa menahan berat badan sama sekali; lutut terlihat berubah bentuk; bengkak besar muncul mendadak setelah cedera; terdengar bunyi 'pop' keras saat cedera lalu lutut lemas; nyeri disertai demam, kemerahan, dan terasa panas (dugaan infeksi); atau nyeri tidak membaik setelah 1-2 minggu perawatan mandiri. Pada lansia, nyeri lutut kronis yang mengganggu tidur dan aktivitas sehari-hari sebaiknya dievaluasi dokter untuk kemungkinan osteoarthritis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Catatan Penting dan Penyelesaian$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Artikel ini bersifat informasi umum, bukan pengganti nasihat medis profesional$$, $$Konsultasikan ke dokter bila ragu dengan penyebab nyeri Anda$$, $$Jaga berat badan ideal — setiap 1 kg berlebih menambah beban lutut berkali lipat$$, $$Perkuat otot paha dengan latihan ringan (misalnya angkat kaki lurus) untuk menopang lutut$$, $$Gunakan alas kaki yang baik dan hindari aktivitas benturan tinggi bila lutut sering nyeri$$, $$Pemeriksaan hasil: nyeri berkurang dalam 3-5 hari dan bisa berjalan normal tanpa pincang$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Indonesia, Negeri Seribu Air Terjun$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Indonesia yang bergunung-gunung dan beriklim tropis basah adalah surga air terjun. Dari Jawa, Sumatera, Bali, hingga Sulawesi, ratusan air terjun tersebar — sebagian sudah mendunia, sebagian masih perawan. Air terjun bukan sekadar pemandangan indah: ia adalah penanda kesehatan hutan di hulunya. Semakin jernih dan stabil debit air terjun, semakin baik kondisi hutan daerah tangkapan airnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Tumpak Sewu: Niagara-nya Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Tumpak Sewu di perbatasan Lumajang-Malang, Jawa Timur, dijuluki 'Niagara-nya Indonesia'. Berbeda dari air terjun tunggal yang tinggi, Tumpak Sewu adalah tirai air selebar hampir 100 meter yang jatuh dari ketinggian sekitar 120 meter, berlatar Gunung Semeru. Aliran utamanya berasal dari mata air di lereng Semeru. Waktu terbaik berkunjung adalah pagi hari saat kabut tipis masih menyelimuti lembah, dan musim kemarau agar jalur turun tidak terlalu licin.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Sekumpul: Mahkota Air Terjun Bali$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Air Terjun Sekumpul di Buleleng, Bali, terdiri dari tujuh aliran air yang jatuh berdampingan dari tebing setinggi sekitar 80 meter — karena itu disebut 'sekumpul' (sekumpulan). Airnya berasal dari hutan lindung di dataran tinggi Bedugul. Untuk mencapainya, pengunjung menuruni ratusan anak tangga dan menyeberangi sungai kecil, tetapi pemandangan tujuh tirai air yang jatuh serentak membuat perjuangan itu terbayar lunas.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Madakaripura: Air Terjun Abadi Para Raja$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Air Terjun Madakaripura di Probolinggo, Jawa Timur, memiliki ketinggian sekitar 200 meter dan dikelilingi tebing curam berlumut yang membentuk lorong sempit. Konon, Patih Gajah Mada menghabiskan masa tua di tempat ini — nama Madakaripura berasal dari 'Mada' dan 'karipura' (tempat terakhir). Keunikannya: debit airnya relatif stabil sepanjang tahun karena berasal dari mata air abadi, dan pengunjung berjalan di antara tirai air yang jatuh dari celah tebing.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Menjaga Air Terjun Berarti Menjaga Hutan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Air terjun yang debitnya menyusut di musim kemarau atau keruh setelah hujan ringan adalah tanda hutan di hulunya rusak. Ancaman terbesar adalah alih fungsi hutan menjadi kebun dan pemukiman liar di daerah tangkapan air. Sebagai pengunjung, kita bisa berkontribusi: tidak membuang sampah di aliran sungai, tidak mencoret-coret tebing, mematuhi jalur resmi, dan memilih pemandu lokal agar ekonomi masyarakat sekitar tumbuh dari pariwisata lestari — bukan dari menebang hutan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Matahari: Pembangkit Listrik Terbesar yang Gratis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setiap jam, Matahari memancarkan energi ke Bumi setara dengan kebutuhan listrik seluruh umat manusia selama setahun. Teknologi solar — panel surya — adalah cara menangkap sebagian kecil energi raksasa itu dan mengubahnya menjadi listrik yang bisa dipakai di rumah, kantor, hingga desa terpencil. Dalam dua dekade terakhir, harga panel surya turun lebih dari 80 persen, membuatnya menjadi sumber energi baru terbarukan yang paling cepat berkembang di dunia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja Panel Surya: Efek Fotovoltaik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Panel surya tersusun dari sel-sel fotovoltaik berbahan silikon. Ketika foton cahaya Matahari menabrak sel, ia melepaskan elektron dari atom silikon — aliran elektron inilah arus listrik searah (DC). Inverter kemudian mengubahnya menjadi arus bolak-balik (AC) yang dipakai peralatan rumah tangga. Efisiensi panel komersial saat ini sekitar 20-23 persen, artinya seperlima cahaya yang datang diubah menjadi listrik; sisanya menjadi panas atau terpantul.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis Panel: Monokristalin, Polikristalin, dan Film Tipis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Panel monokristalin (hitam pekat) paling efisien dan awet, cocok untuk atap rumah yang luasnya terbatas. Panel polikristalin (biru bercorak) sedikit kurang efisien tetapi lebih murah. Panel film tipis ringan dan fleksibel, bisa dipasang di permukaan lengkung, tetapi efisiensinya paling rendah dan butuh lahan lebih luas. Untuk rumah tinggal di Indonesia, monokristalin umumnya pilihan terbaik karena keterbatasan luas atap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Potensi Indonesia: Surga Energi Surya Khatulistiwa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Indonesia dilewati garis khatulistiwa sehingga mendapat penyinaran Matahari hampir 12 jam sehari sepanjang tahun — potensi energi suryanya termasuk terbesar di dunia. Atap-atap rumah, gedung perkantoran, dan lahan tidak produktif bisa menjadi pembangkit mini. Program PLTS atap memungkinkan rumah tangga menyalurkan kelebihan listrik ke jaringan PLN. Di daerah terpencil yang belum terjangkau jaringan listrik, PLTS komunal plus baterai sudah menerangi ribuan desa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tantangan dan Masa Depan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tantangan terbesar energi surya adalah sifatnya yang intermiten — tidak berproduksi di malam hari dan menurun saat mendung — sehingga butuh baterai penyimpan atau cadangan dari jaringan. Biaya awal pemasangan juga masih terasa, meski terus turun. Namun masa depan cerah: efisiensi sel terus naik, baterai makin murah, dan konsep seperti panel surya transparan untuk jendela gedung serta pembangkit surya terapung di waduk mulai diterapkan. Dalam satu-dua dekade ke depan, atap yang menghasilkan listrik sendiri bisa menjadi hal biasa.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$$Menjelaskan pengertian kesebangunan dua bangun datar$$, $$Menentukan syarat dua bangun datar sebangun$$, $$Menghitung panjang sisi yang belum diketahui pada bangun sebangun$$, $$Menyelesaikan masalah kesebangunan pada segitiga$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Kesebangunan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Dua bangun datar dikatakan sebangun (simbol ~) jika bentuknya sama tetapi ukurannya bisa berbeda — seperti foto yang dicetak dalam dua ukuran berbeda. Secara matematis, dua bangun sebangun bila: (1) sudut-sudut yang bersesuaian sama besar, dan (2) sisi-sisi yang bersesuaian memiliki perbandingan yang sama (senilai). Contoh: semua persegi pasti sebangun satu sama lain, dan semua lingkaran pasti sebangun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Syarat Dua Bangun Datar Sebangun$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Sudut-sudut yang bersesuaian sama besar: sudut A = sudut A', sudut B = sudut B', dan seterusnya$$, $$Sisi-sisi yang bersesuaian sebanding: AB/A'B' = BC/B'C' = CD/C'D' = ... = k (faktor skala)$$, $$Catatan: dua bangun yang kongruen pasti sebangun, tetapi yang sebangun belum tentu kongruen$$, $$Semua bangun beraturan (persegi, segitiga sama sisi, lingkaran) selalu sebangun dengan sesamanya$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Diketahui persegi panjang ABCD sebangun dengan EFGH. AB = 12 cm, BC = 8 cm, EF = 18 cm. Tentukan FG! Penyelesaian: karena sebangun, AB/EF = BC/FG. Substitusi: 12/18 = 8/FG, sederhanakan 12/18 = 2/3. Maka 2/3 = 8/FG, kali silang: 2 x FG = 24, sehingga FG = 12 cm. Jadi sisi FG = 12 cm.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Kesebangunan pada Segitiga$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Dua segitiga sebangun jika memenuhi salah satu syarat: (1) ketiga sudut yang bersesuaian sama besar; (2) dua pasang sisi yang bersesuaian sebanding dan sudut apitnya sama; atau (3) ketiga pasang sisi yang bersesuaian sebanding. Kesebangunan segitiga dipakai untuk mengukur tinggi benda yang sulit dijangkau, misalnya tinggi pohon atau gedung, dengan bantuan bayangan dan segitiga sebangun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Persegi ABCD dengan sisi 6 cm sebangun dengan persegi PQRS dengan sisi 9 cm. Tentukan faktor skala dari ABCD ke PQRS! (Kunci: faktor skala = 9/6 = 3/2 atau 1,5 kali)$$, $$2. Segitiga ABC sebangun dengan segitiga DEF. AB = 9 cm, DE = 12 cm, BC = 6 cm. Tentukan panjang EF! (Kunci: AB/DE = BC/EF, 9/12 = 6/EF, EF = 8 cm)$$, $$3. Sebuah foto berukuran 8 cm x 12 cm diperbesar sehingga lebarnya menjadi 18 cm. Berapa tinggi foto setelah diperbesar agar tetap sebangun? (Kunci: 8/12 = 18/tinggi, tinggi = 27 cm)$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$$Menjelaskan pengertian drama dengan bahasa sendiri$$, $$Menyebutkan unsur-unsur drama$$, $$Membaca naskah drama pendek dengan lafal dan intonasi tepat$$, $$Mempraktikkan bermain drama sederhana bersama teman$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Drama$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Drama adalah karya sastra yang menceritakan kisah lewat dialog (percakapan) para tokoh dan dipentaskan di depan penonton. Berbeda dengan cerita biasa yang dinarasikan, drama 'hidup' ketika dimainkan: ada pemain yang menjadi tokoh, ada gerak-gerik, ada latar panggung, dan ada penonton yang menyaksikan. Contoh drama yang kamu kenal: sandiwara, ketoprak, lenong, dan drama musikal di televisi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Unsur-Unsur Drama$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Naskah: teks berisi dialog dan petunjuk lakuan pemain$$, $$Tokoh: pelaku cerita — ada tokoh utama, tokoh pembantu, protagonis (baik) dan antagonis (jahat)$$, $$Dialog: percakapan antar tokoh yang memajukan cerita$$, $$Babak dan adegan: pembagian bagian cerita dalam pementasan$$, $$Latar: tempat, waktu, dan suasana terjadinya cerita$$, $$Amanat: pesan moral yang ingin disampaikan kepada penonton$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Naskah Drama Pendek$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Judul: 'Kejujuran Dito'. Tokoh: Dito, Ibu, Pak Guru. Adegan 1 — Di rumah pagi hari. Dito: (gugup) Bu... nilai ulanganku kemarin jelek. Ibu: (tersenyum) Tidak apa-apa, Nak. Yang penting Dito jujur dan mau belajar lebih giat. Dito: (lega) Terima kasih, Bu. Dito janji akan belajar sungguh-sungguh. Adegan 2 — Di sekolah. Pak Guru: Dito, Ibu sudah bercerita. Bapak bangga kamu berani jujur. Kejujuran lebih berharga daripada nilai bagus yang didapat dengan mencontek.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Cara Bermain Drama yang Baik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Pertama, pahami tokohmu: bagaimana sifatnya, bagaimana ia berbicara. Kedua, hafalkan dialog secukupnya — boleh improvisasi asal tidak mengubah jalan cerita. Ketiga, gunakan intonasi sesuai perasaan tokoh: sedih suaranya pelan, marah suaranya tegas. Keempat, gerak tubuh harus jelas terlihat penonton. Kelima, kerja sama tim: dengarkan dialog lawan mainmu agar adegan mengalir. Latihan 2-3 kali sebelum pentas membuat penampilan jauh lebih percaya diri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Apa perbedaan drama dengan cerita pendek? Jelaskan dengan bahasamu sendiri! (Kunci: drama ditulis dalam bentuk dialog untuk dipentaskan, sedangkan cerita pendek dinarasikan untuk dibaca)$$, $$2. Sebutkan 4 unsur drama beserta penjelasannya! (Kunci: naskah, tokoh, dialog, babak/adegan, latar, amanat — sebutkan 4 dengan benar)$$, $$3. Buatlah dialog pendek (4-6 kalimat) antara dua tokoh tentang gotong royong membersihkan kelas! (Kunci: dinilai dari dua tokoh, dialog wajar, tema gotong royong jelas, ejaan dan tanda baca tepat)$$])));
